WITH source_row AS (
    SELECT source_id FROM external_sources WHERE source_name = 'ESPN'
), team_rows AS (
    SELECT DISTINCT ON (fifa_code) *
    FROM _espn_team_seed
    ORDER BY fifa_code, espn_team_id
)
UPDATE teams team_row
SET
    abbreviation = COALESCE(NULLIF(team_rows.abbreviation, ''), team_row.abbreviation),
    logo_url = COALESCE(NULLIF(team_rows.logo_url, ''), team_row.logo_url),
    primary_color = COALESCE(NULLIF(team_rows.primary_color, ''), team_row.primary_color)
FROM team_rows
JOIN countries country ON country.fifa_code = team_rows.fifa_code
WHERE team_row.country_id = country.country_id;

WITH source_row AS (
    SELECT source_id FROM external_sources WHERE source_name = 'ESPN'
), team_rows AS (
    SELECT DISTINCT ON (fifa_code) *
    FROM _espn_team_seed
    ORDER BY fifa_code, espn_team_id
)
INSERT INTO source_records (source_id, entity_type, entity_id, external_id, source_url, raw_payload)
SELECT
    source_row.source_id,
    'team',
    team_row.team_id,
    team_rows.espn_team_id,
    team_rows.clubhouse_url,
    team_rows.raw_payload || jsonb_build_object(
        'fifa_code', team_rows.fifa_code,
        'espn_slug', team_rows.espn_slug,
        'squad_url', team_rows.squad_url
    )
FROM team_rows
CROSS JOIN source_row
JOIN countries country ON country.fifa_code = team_rows.fifa_code
JOIN teams team_row ON team_row.country_id = country.country_id
ON CONFLICT (source_id, entity_type, external_id) DO UPDATE SET
    entity_id = EXCLUDED.entity_id,
    source_url = EXCLUDED.source_url,
    raw_payload = EXCLUDED.raw_payload,
    last_seen_at = now();

DO $$
DECLARE
    seed_row RECORD;
    v_source_id BIGINT;
    v_tournament_id BIGINT;
    v_team_id BIGINT;
    v_country_id BIGINT;
    v_player_id BIGINT;
BEGIN
    SELECT source_id INTO v_source_id
    FROM external_sources
    WHERE source_name = 'ESPN';

    SELECT tournament_id INTO v_tournament_id
    FROM tournaments WHERE name = 'FIFA World Cup 2026';

    FOR seed_row IN
        SELECT DISTINCT ON (espn_player_id, fifa_code) *
        FROM _espn_squad_seed
        ORDER BY espn_player_id, fifa_code, player_name
    LOOP
        SELECT team_row.team_id, country.country_id
        INTO v_team_id, v_country_id
        FROM teams team_row
        JOIN countries country ON country.country_id = team_row.country_id
        WHERE country.fifa_code = seed_row.fifa_code;

        SELECT source_record.entity_id
        INTO v_player_id
        FROM source_records source_record
        WHERE source_record.source_id = v_source_id
          AND source_record.entity_type = 'player'
          AND source_record.external_id = seed_row.espn_player_id;

        IF v_player_id IS NULL THEN
            INSERT INTO players (
                display_name, short_name, first_name, last_name, nationality,
                nationality_country_id, height_text, weight_text
            ) VALUES (
                seed_row.player_name, seed_row.short_name, seed_row.first_name, seed_row.last_name,
                seed_row.nationality, v_country_id, seed_row.height_text, seed_row.weight_text
            )
            RETURNING player_id INTO v_player_id;
        ELSE
            UPDATE players
            SET
                display_name = seed_row.player_name,
                short_name = seed_row.short_name,
                first_name = seed_row.first_name,
                last_name = seed_row.last_name,
                nationality = seed_row.nationality,
                nationality_country_id = v_country_id,
                height_text = seed_row.height_text,
                weight_text = seed_row.weight_text
            WHERE player_id = v_player_id;
        END IF;

        INSERT INTO source_records (
            source_id, entity_type, entity_id, external_id, source_url, raw_payload
        ) VALUES (
            v_source_id, 'player', v_player_id, seed_row.espn_player_id,
            seed_row.source_url, seed_row.raw_payload
        )
        ON CONFLICT (source_id, entity_type, external_id) DO UPDATE SET
            entity_id = EXCLUDED.entity_id,
            source_url = EXCLUDED.source_url,
            raw_payload = EXCLUDED.raw_payload,
            last_seen_at = now();

        INSERT INTO squad_memberships (
            tournament_id, team_id, player_id, jersey_number, position_code, position_name,
            roster_group, age, source_id, source_url, raw_payload
        ) VALUES (
            v_tournament_id, v_team_id, v_player_id, seed_row.jersey_number,
            seed_row.position_code, seed_row.position_name, seed_row.roster_group, seed_row.age,
            v_source_id, seed_row.source_url, seed_row.raw_payload
        )
        ON CONFLICT (tournament_id, team_id, player_id) DO UPDATE SET
            jersey_number = EXCLUDED.jersey_number,
            position_code = EXCLUDED.position_code,
            position_name = EXCLUDED.position_name,
            roster_group = EXCLUDED.roster_group,
            age = EXCLUDED.age,
            is_active = true,
            source_id = EXCLUDED.source_id,
            source_url = EXCLUDED.source_url,
            raw_payload = EXCLUDED.raw_payload;
    END LOOP;
END $$;

-- Import notes:
-- - CUW Curaçao: no squad groups found in ESPN payload

COMMIT;
